function formatBalance(n) {
  const v = Number(n || 0);
  if (v >= 1000000) return `${Number((v / 1000000).toFixed(2))}M`;
  if (v >= 1000) return `${Math.round(v / 1000)}K`;
  return v.toLocaleString('en-US', { maximumFractionDigits: 2 });
}

