/* Flat icon-rail list (collapsed sidebar for logged-in users). Reuses the
   same icons; dividers mirror the drawer's groups. */
export const RAIL_ITEMS = [
  { id: 'promotions', label: 'Promotions', icon: ICON.promotions, to: '/promotions', authRequired: true },
  { id: 'install', label: 'Install App', icon: ICON.install, to: '/install' },
  { id: 'referral', label: 'Referral', icon: ICON.referral, to: '/account/affiliate', authRequired: true },
  { divider: true },
  { id: 'vip', label: 'VIP', icon: ICON.vip, to: '/vip', authRequired: true },
  // Favorites disabled (no backend management)
  // { id: 'favorites', label: 'Favorites', icon: ICON.favorites, to: '/favorites', authRequired: true },
  { id: 'faq', label: 'FAQ', icon: ICON.faq, to: '/faq' },
  { divider: true },
  ...GAME_ITEMS.map((g) => ({ id: g.id, label: g.label, icon: g.icon, to: getGameCategoryPath(g.id) })),
  { divider: true },
  { id: 'spin', label: 'Spin the Wheel', icon: ICON.spin, to: '/spinwheel', authRequired: true },
  { id: 'daily', label: 'Daily Rewards', icon: ICON.promotions, to: '/daily-bonus', authRequired: true },
  { id: 'missions', label: 'Weekly Missions', icon: ICON.bonuses, to: '/promotions', authRequired: true },
  { divider: true },
  { id: 'providers', label: 'Providers', icon: ICON.providers, to: '/providers' },
  { id: 'responsible', label: 'Responsible Gaming Policy', icon: ICON.responsible, to: '/responsible-gaming' },
  { id: 'support', label: 'Support', icon: ICON.support, action: 'support' },
  { id: 'blog', label: 'Blog', icon: ICON.blog, to: '/blog' },
  { id: 'tutorial', label: 'Tutorial', icon: ICON.tutorial, to: '/install' },
  { divider: true },
  { id: 'logout', label: 'Logout', icon: ICON.logout, action: 'logout' },
];

/** Rail items with the admin's labels applied and switched-off items (and their orphan dividers) removed. */
export function applyRailShell(items, shell) {
  const kept = items
    .filter((it) => it.divider || !shell.hidden('sidebar', it.id))
    .map((it) => (it.divider ? it : { ...it, label: shell.label('sidebar', it.id, it.label) }));
  return kept.filter((it, i) => !(it.divider && (i === 0 || i === kept.length - 1 || kept[i - 1].divider)));
}

/**
 * Dashboard left rail — Golden-Dragon-style lobby sidebar,
 * exact option set + icons, DragonFury assets, no purple.
 */
export function DashboardSidebar({ onNavigate, isAuthenticated = true }) {
  const navigate = useNavigate();
  const { pathname } = useLocation();
  const { balanceSc, balanceGc, logout } = useAuth();
  const [gamesOpen, setGamesOpen] = useState(false);
  const [bonusesOpen, setBonusesOpen] = useState(false);
  const shell = useLobbyShell();
  // Only legal pages that are enabled (and filled in) in the backend; Responsible Gaming already has its own row.
  const legalLinks = useLegalPageLinks().filter((l) => l.to !== '/responsible-gaming');
  const isCategoryAvailable = useAvailableGameCategories();
  const { vipStatus } = useVipStatus();
  const vipLevels = Array.isArray(vipStatus?.levels) ? vipStatus.levels : [];
  const vipIdx = Number(vipStatus?.level_index) || 0;
  const vipName = vipStatus?.level_name || vipLevels[vipIdx]?.name || 'Iron';
  const vipNextLevel = !vipStatus?.is_max_level ? vipLevels[vipIdx + 1] : null;
  const vipNeed = Number(vipStatus?.next_level_xp) || 0;
  const vipNext = vipNextLevel ? { name: vipNextLevel.name || 'Next', xp: vipNeed || (vipLevels[vipIdx]?.xp_to_next_level ?? '') } : null;
  const vipPct = vipNeed > 0 ? Math.max(0, Math.min(100, ((Number(vipStatus?.current_xp) || 0) / vipNeed) * 100)) : (vipStatus?.is_max_level ? 100 : 0);

  const go = (to) => {
    navigate(isAuthenticated ? to : '/register');
    onNavigate?.();
  };
  const isActive = (to) => pathname === to || pathname.startsWith(`${to}/`);

  // `id` is the admin's handle for the item (label override + on/off).
  const Row = ({ id, icon, label, to, onClick, badge }) => (shell.hidden('sidebar', id) ? null : (
    <button
      type="button"
      className={`dgs__row${to && isActive(to) ? ' is-active' : ''}`}
      onClick={() => (onClick ? onClick() : go(to))}
    >
      <span className="dgs__row-ico">{icon}</span>
      <span className="dgs__row-label">{shell.label('sidebar', id, label)}</span>
      {badge ? <span className="dgs__row-badge">{badge}</span> : null}
    </button>
  ));

  return (
    <aside className="dgs" aria-label="Dashboard navigation w-100">
      <Link to="/casino" className="dgs__logo" aria-label={`${site.platformName} home`} onClick={onNavigate}>
        <img src={shell.text('sidebar.logo', LOGO_SRC)} alt={site.platformName} width="200" height="107" draggable="false" />
        <img className="dgs__logo-glow" src={LOGO_GLOW_SRC} alt="" aria-hidden width="347" height="248" draggable="false" />
      </Link>

      <div className="dgs__scroll">
        {isAuthenticated ? (
          <>
          {/* ---- balance card ---- */}
          <div className="dgs__card dgs__balance">
            <span className="dgs__balance-ribbon">{shell.text('sidebar.balance', 'Your Balance')}</span>
            <div className="dgs__balance-body">
              <img className="dgs__balance-vault" src={VAULT_SRC} onError={onImgFallback(VAULT_FALLBACK)} alt="" aria-hidden draggable="false" />
              <div className="dgs__pills">
                <div className="dgs__pill dgs__pill--gc">
                  <img src={GC_COIN_SRC} alt="Gold Coins" />
                  <span>{formatBalance(balanceGc)}</span>
                </div>
                <div className="dgs__pill dgs__pill--sc">
                  <img src={SC_COIN_SRC} alt="Sweep Coins" />
                  <span>{formatBalance(balanceSc)}</span>
                </div>
              </div>
            </div>
            <div className="dgs__balance-actions">
              <Link to={isAuthenticated ? '/store' : '/register'} className="dgs__rim dgs__rim--buy" onClick={isAuthenticated ? storeLinkClick('buy', onNavigate) : onNavigate}>
                <span className="dgs__store-btn dgs__store-btn--buy">{shell.text('sidebar.buy', 'Buy')}</span>
              </Link>
              <Link to={isAuthenticated ? '/redeem' : '/register'} className="dgs__rim dgs__rim--redeem" onClick={isAuthenticated ? storeLinkClick('redeem', onNavigate) : onNavigate}>
                <span className="dgs__store-btn dgs__store-btn--redeem">{shell.text('sidebar.redeemBtn', 'Redeem')}</span>
              </Link>
            </div>
          </div>

          {/* ---- vip card ---- */}
          <div className="dgs__card dgs__vip">
            <Link to="/vip" className="dgs__vip-link" onClick={onNavigate}>
              <img className="dgs__vip-tier" src={VIP_TIER_SRC} onError={onImgFallback(VIP_TIER_FALLBACK)} alt="" aria-hidden draggable="false" />
              <div className="dgs__vip-meta">
                <div className="dgs__vip-row">
                  <b>{shell.text('sidebar.vipLevel', 'VIP Level')}</b>
                  <span>{vipName}</span>
                </div>
                <div className="dgs__vip-track">
                  <div className="dgs__vip-fill" style={{ width: `${vipPct}%` }} />
                </div>
                <div className="dgs__vip-next">
                  <span>{vipNext ? 'Next Level' : 'Top Level'}</span>
                  <b>{vipNext ? `${vipNext.name} ${vipNext.xp}` : vipName}</b>
                </div>
              </div>
            </Link>
            <button type="button" className="dgs__vip-info" aria-label="VIP info" onClick={() => go('/vip')}>
              {ICON.info}
            </button>
          </div>
          </>
        ) : (
          /* ---- guest: referral banner instead of balance / VIP points ---- */
          <Link to="/register" className="dgs__refer" onClick={onNavigate}>
            <span className="dgs__refer-text">
              <b>{shell.text('sidebar.referTitle', 'Refer a Friend')}</b>
              <span>{shell.text('sidebar.referSub', 'Earn free coins')}</span>
            </span>
            <img className="dgs__refer-img" src={REFER_BOX_SRC} alt="" aria-hidden draggable="false" />
          </Link>
        )}

        <div className="dgs__divider" aria-hidden />

        <nav className="dgs__nav">
          <Row id="promotions" icon={ICON.promotions} label="Promotions" to="/promotions" />
          <Row id="install" icon={ICON.install} label="Install App" to="/install" />
          <Row id="referral" icon={ICON.referral} label="Referral" to="/account/affiliate" />

          <div className="dgs__divider" aria-hidden />

          <Row id="vip" icon={ICON.vip} label="VIP" to="/vip" />
          {/* Favorites disabled (no backend management)
          <Row id="favorites" icon={ICON.favorites} label="Favorites" to="/favorites" />
          */}
          <Row id="faq" icon={ICON.faq} label="FAQ" to="/faq" />

          <div className="dgs__divider" aria-hidden />

          {shell.hidden('sidebar', 'platforms') ? null : (
            <Link to="/platform" className="dgs__plain" onClick={onNavigate}>
              {shell.label('sidebar', 'platforms', 'Platforms')}
            </Link>
          )}

          <div className="dgs__divider" aria-hidden />

          {/* ---- Games ---- */}
          {shell.hidden('sidebar', 'games') ? null : (
          <div className={`dgs__group${gamesOpen ? ' is-open' : ''}`}>
            <button type="button" className="dgs__group-trigger" onClick={() => setGamesOpen((o) => !o)} aria-expanded={gamesOpen}>
              <span className="dgs__group-trigger-label">
                <span>{shell.label('sidebar', 'games', 'Games')}</span>
              </span>
              {ICON.chevron}
            </button>
            <div className="dgs__group-body">
              {GAME_ITEMS.filter((g) => !shell.hidden('sidebar', g.id) && isCategoryAvailable(g.id)).map((g) => (
                <button
                  key={g.id}
                  type="button"
                  className={`dgs__row${isActive(getGameCategoryPath(g.id)) ? ' is-active' : ''}`}
                  onClick={() => {
                    warmupCasino();
                    go(getGameCategoryPath(g.id));
                  }}
                >
                  <span className="dgs__row-ico">{g.icon}</span>
                  <span className="dgs__row-label">{shell.label('sidebar', g.id, g.label)}</span>
                </button>
              ))}
            </div>
          </div>
          )}

          <div className="dgs__divider" aria-hidden />

          {/* ---- Bonuses ---- */}
          {shell.hidden('sidebar', 'bonuses') ? null : (
          <div className={`dgs__group${bonusesOpen ? ' is-open' : ''}`}>
            <button type="button" className="dgs__group-trigger" onClick={() => setBonusesOpen((o) => !o)} aria-expanded={bonusesOpen}>
              <span className="dgs__group-trigger-label">
                {ICON.bonuses}
                <span>{shell.label('sidebar', 'bonuses', 'Bonuses')}</span>
              </span>
              {ICON.chevron}
            </button>
            <div className="dgs__group-body">
              <Row id="spin" icon={ICON.spin} label="Spin the Wheel" to="/spinwheel" />
              <Row id="daily" icon={ICON.promotions} label="Daily Rewards" to="/daily-bonus" />
              <Row id="missions" icon={ICON.bonuses} label="Weekly Missions" to="/promotions" />
            </div>
          </div>
          )}

          <div className="dgs__divider" aria-hidden />

          <Row id="providers" icon={ICON.providers} label="Providers" to="/providers" />
          <Row id="responsible" icon={ICON.responsible} label="Responsible Gaming Policy" to="/responsible-gaming" />
          <Row id="support" icon={ICON.support} label="Support" onClick={() => openSupportWidget()} />
          <Row id="blog" icon={ICON.blog} label="Blog" to="/blog" />
          <Row id="tutorial" icon={ICON.tutorial} label="Tutorial" onClick={() => go('/install')} />
          {legalLinks.map((l) => (
            <Row
              key={`legal-${l.to}`}
              id={`legal-${l.to.replace(/[^a-z0-9]+/gi, '-')}`}
              icon={ICON.responsible}
              label={l.label}
              to={l.to}
            />
          ))}

          {shell.sidebarLinks.map((l) => (
            <Row
              key={`${l.label}|${l.to}`}
              id={`custom-${l.label.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`}
              icon={ICON.tutorial}
              label={l.label}
              onClick={() => {
                if (/^https?:\/\//i.test(l.to)) window.open(l.to, '_blank', 'noopener,noreferrer');
                else go(l.to);
                onNavigate?.();
              }}
            />
          ))}

          {isAuthenticated ? (
            <>
              <div className="dgs__divider" aria-hidden />
              <Row id="logout" icon={ICON.logout} label="Logout" onClick={() => { logout?.(); onNavigate?.(); }} />
            </>
          ) : null}
        </nav>
      </div>
    </aside>
  );
}

export default DashboardSidebar;
